// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address initializer, address caller) public {
        vm.assume(initializer != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != initializer);
        vm.assume(address(caller).code.length == 0);

        // deploy adversarial helper for glpManager (its vault() is queried during init)
        GlpManagerStub stub = new GlpManagerStub();

        // initialize from the fuzzed initializer address via low-level call (types are interfaces in src)
        vm.prank(initializer);
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "initialize(address,address,address,address,address,address)",
                address(1),
                address(2),
                address(3),
                address(stub),
                address(4),
                address(5)
            )
        );
        assertTrue(ok, "initialize failed");

        // rule: owner() returns the stored owner (initializer), no matter who queries
        vm.prank(caller);
        assertTrue(c.owner() == initializer, "owner() must return the stored owner, not the caller");
    }
}

contract GlpManagerStub {
    function vault() external pure returns (address) {
        return address(0xdead);
    }
}
